<?php require_once __DIR__ . '/includes/init.php'; redirect_if_logged_in(); $errors=[]; if ($_SERVER['REQUEST_METHOD']==='POST') { require_csrf(); $first=trim((string)($_POST['first_name']??'')); $last=trim((string)($_POST['last_name']??'')); $email=strtolower(trim((string)($_POST['email']??''))); $password=(string)($_POST['password']??''); if($first===''||$last==='')$errors[]='Please enter your name.'; if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Please enter a valid email.'; if($error=password_error($password))$errors[]=$error; if(!$errors && db_one('SELECT id FROM users WHERE email = ?',[$email]))$errors[]='An account with this email already exists.'; if(!$errors){db_query('INSERT INTO users (first_name,last_name,email,password_hash) VALUES (?,?,?,?)',[$first,$last,$email,password_hash($password,PASSWORD_DEFAULT)]); login_user(['id'=>db()->lastInsertId()]); redirect('account.php');}} $pageTitle='Create account'; require __DIR__.'/includes/header.php'; ?><main class="container auth-page"><div class="auth-card"><p class="eyebrow">Join BFM</p><h1>Create your account</h1><?php foreach($errors as $error): ?><div class="alert alert-error"><?=e($error)?></div><?php endforeach; ?><form method="post" class="form-stack"><?=csrf_field()?><div class="form-grid"><label>First name<input name="first_name" required></label><label>Last name<input name="last_name" required></label></div><label>Email<input type="email" name="email" required autocomplete="email"></label><label>Password<input type="password" name="password" required autocomplete="new-password"><small>At least 8 characters with a letter and number.</small></label><button class="btn btn-primary btn-block">Create account</button></form><p class="auth-link">Already have an account? <a href="<?=e(url('login.php'))?>">Log in</a></p></div></main><?php require __DIR__.'/includes/footer.php'; ?>
